// The checks of the Fission products lessons "Air on hot graphite"
// (chem-air.html), "Steam on graphite and bare kernels" (chem-steam.html) and
// "Into the source term" (atops-source-term.html), under node (no browser):
// `node docs/site/science/fission-products/check-chemhand.js`.
// Data: chemhand-data.js, generated by crates/dhoby-ghaut/examples/
// lesson_chemistry_handoff (predictions C1-C8, S1-S2 in its module doc).
// Gates: boon-lay's own transcription values, the code's branches and
// flags read back from the data, the record copied unchanged, and the pages'
// wiring. Lines marked "REPORT" print a prediction against its result (HIT
// or MISS); they are not gates. Results of 2026-11-04 in the comments.
"use strict";
const fs = require("fs"), path = require("path");
global.window = {};
eval(fs.readFileSync(path.join(__dirname, "chemhand-data.js"), "utf8"));
const D = window.CHEMHAND_DATA;
let failed = 0;
function check(name, value, limit) {
  const ok = value <= limit;
  if (!ok) failed++;
  console.log(`${ok ? "ok  " : "FAIL"} ${name}: ${value.toExponential(2)} (limit ${limit})`);
}
function report(name, hit, text) { console.log(`REPORT ${name}: ${hit ? "HIT" : "MISS"} ${text}`); }
const rel = (a, b) => Math.abs(a / b - 1);
const T = D.tC, n = T.length;

// 1. Shapes: every recorded curve is on the 121-point grid.
let bad = 0;
D.air.curves.forEach((c) => ["rate", "inside", "kineticMol", "gasifiedMol", "supplyBinds"].forEach((k) => { if (c[k].length !== n) bad++; }));
D.steam.forEach((s) => { if (s.hydrolysis.length !== n || s.hydrolysisFlag.length !== n) bad++; s.graphite.forEach((g) => { if (g.rate.length !== n || g.inside.length !== n) bad++; }); });
check("1 curves on the 400-1600 °C grid (121 points)", bad + Math.abs(n - 121), 0);

// 2. Air, boon-lay's transcription value (graphite_air test, 6.8877e-6 /s at 650 °C).
check("2 air rate at 650 °C in air vs 6.8877e-6 /s", rel(D.airAt.r650, 6.8877e-6), 1e-4);

// 3. Air: first order in O2 (the labelled assumption), read from the data.
let w3 = 0;
const airRef = D.air.curves[D.air.curves.length - 1];
D.air.curves.forEach((c) => c.rate.forEach((r, i) => { w3 = Math.max(w3, Math.abs(r / airRef.rate[i] - c.o2kPa / airRef.o2kPa)); }));
check("3 air rate ratio vs the O2 pressure ratio, worst", w3, 1e-12);

// 4. Air: what the code returns is min(kinetic, supply), and the flag says
//    which. 2026-11-04: exact at every point.
let w4 = 0;
D.air.curves.forEach((c) => c.gasifiedMol.forEach((g, i) => {
  const k = c.kineticMol[i], s = D.air.supplyMolPerS;
  if (g !== Math.min(k, s)) w4++;
  if ((c.supplyBinds[i] === 1) !== (k > s)) w4++;
}));
check("4 gasified = min(kinetic, supply) and the limit flag agrees", w4, 0);

// 5. C1: the measured range on the grid is 600-690 °C at every pressure.
let w5 = 0;
D.air.curves.forEach((c) => T.forEach((t, i) => { if ((c.inside[i] === 1) !== (t >= 600 && t <= 690)) w5++; }));
check("5 C1: air 'inside' flags exactly at 600-690 °C", w5, 0);
report("C2 air rate 900 °C ≈ 1.39e-3 /s within 5 %", rel(D.airAt.r900, 1.39e-3) < 0.05, D.airAt.r900.toExponential(4));
const cAir = airRef.crossoverC, c1 = D.air.curves.filter((c) => c.o2kPa === 1)[0].crossoverC;
report("C3 supply binds from ≈ 612 °C in air (±10)", Math.abs(cAir - 612) <= 10, cAir.toFixed(2) + " °C");
report("C3 supply binds from ≈ 731 °C at 1 kPa (±10)", Math.abs(c1 - 731) <= 10, c1.toFixed(2) + " °C");
report("C4 kinetic/supply at 900 °C ≈ 580 (5 %)", rel(D.airAt.ratio900, 580) < 0.05, D.airAt.ratio900.toFixed(1));

// 6. Steam: boon-lay's transcription value (2.004984e-6 /s, 1050 °C, 5 kPa, no H2).
check("6 steam rate 1050 °C 5 kPa vs 2.004984e-6 /s", rel(D.steamAt.r1050, 2.004984e-6), 1e-4);
report("C5 1 kPa H2 cuts it to ≈ 0.45 (3 %)", rel(D.steamAt.r1050H2 / D.steamAt.r1050, 0.45) < 0.03, (D.steamAt.r1050H2 / D.steamAt.r1050).toFixed(4));

// 7. Steam: the measured box (C6), and hydrogen never speeds it up.
let w7 = 0, w7h = 0;
D.steam.forEach((s) => s.graphite.forEach((g) => T.forEach((t, i) => {
  const want = t >= 850 && t <= 1100 && s.kPa >= 0.5 && s.kPa <= 20;
  if ((g.inside[i] === 1) !== want) w7++;
  if (g.h2kPa > 0 && g.rate[i] > s.graphite[0].rate[i]) w7h++;
})));
check("7 C6: steam 'inside' flags exactly in the measured box", w7, 0);
check("7 hydrogen never raises the steam rate", w7h, 0);

// 8. Kernel hydrolysis: in [0, 1]; clamped (flag 2) exactly where the value
//    is 1; inside (flag 0) only in 820-1040 °C at 2.8-1051 Pa.
let w8 = 0;
D.steam.forEach((s) => s.hydrolysis.forEach((f, i) => {
  const fl = s.hydrolysisFlag[i], t = T[i], pa = s.kPa * 1e3;
  if (f < 0 || f > 1) w8++;
  if ((fl === 2) !== (f === 1)) w8++;
  if (fl === 0 && !(t >= 820 && t <= 1040 && pa >= 2.8 && pa <= 1051)) w8++;
}));
check("8 hydrolysis bounded, clamp flag = value 1, 'inside' only in the fit", w8, 0);
// Boon-lay's own check, f = 0.296875 at 1000 °C and 1000 Pa (1 kPa is recorded).
const s1 = D.steam.filter((s) => s.kPa === 1)[0];
check("8 hydrolysis at 1000 °C, 1 kPa vs 0.296875", rel(s1.hydrolysis[T.indexOf(1000)], 0.296875), 1e-4);
report("C7 whole inventory at 1000 °C ≈ 5.0 kPa (10 %)", rel(D.wholeInventory.at1000, 5.0) < 0.1, D.wholeInventory.at1000.toFixed(3) + " kPa");
report("C7 whole inventory at 770 °C ≈ 2.4 kPa (10 %)", rel(D.wholeInventory.at770, 2.4) < 0.1, D.wholeInventory.at770.toFixed(3) + " kPa");
const s300 = D.steam.filter((s) => s.kPa === 300)[0];
let lastClamp = -1; s300.hydrolysisFlag.forEach((f, i) => { if (f === 2) lastClamp = i; });
const contiguous = s300.hydrolysisFlag.slice(0, lastClamp + 1).every((f) => f === 2) && s300.hydrolysisFlag.slice(lastClamp + 1).every((f) => f !== 2);
report("C8 at 300 kPa clamped from 400 °C to 1150-1250 °C, below 1 above (≈ 3.5e-3 at 1600)", contiguous && T[lastClamp] >= 1150 && T[lastClamp] <= 1250 && rel(s300.hydrolysis[n - 1], 3.5e-3) < 0.2,
  `clamped to ${T[lastClamp]} °C, contiguous ${contiguous}, f(1600) = ${s300.hydrolysis[n - 1].toExponential(3)}`);
// The page says the 300 kPa kernel curve drops below 1 at the hottest temperatures.
check("8 at 300 kPa the hydrolysis fit is below 1 at 1600 °C (chem-steam.html says so)", s300.hydrolysis[n - 1] < 1 ? 0 : 1, 0);

// 9. The source term is the record, copied: fractions are the ratio, the six
//    are less than the total, the provenance carries the re-run date.
const S = D.source;
let w9 = 0;
S.nuclides.forEach((x) => { if (x.fraction !== x.releasedBq / x.inventoryBq) w9++; });
check("9 released fraction = released / inventory", w9, 0);
check("9 the six nuclides are less than the recorded total", S.sixBq < S.totalBq ? 0 : 1, 0);
check("9 provenance names the 2026-10-04 re-run", S.provenance.includes("2026-10-04") ? 0 : 1, 0);
check("9 sum of the six recorded = sixBq", rel(S.nuclides.reduce((a, x) => a + x.releasedBq, 0), S.sixBq), 1e-15);
const f = (nm) => S.nuclides.filter((x) => x.name === nm)[0].fraction;
report("S1 Xe-133, I-131, I-133 ≈ 1.91e-4; Cs-137 1.02e-3; Ag-110m 2.49e-2 (3 figures)",
  ["Xe-133", "I-131", "I-133"].every((nm) => Math.abs(f(nm) - 1.91e-4) < 0.005e-4) && Math.abs(f("Cs-137") - 1.02e-3) < 0.005e-3 && Math.abs(f("Ag-110m") - 2.49e-2) < 0.005e-2,
  S.nuclides.map((x) => `${x.name} ${x.fraction.toExponential(3)}`).join(", "));
const order = S.nuclides.slice().sort((a, b) => b.releasedBq - a.releasedBq).map((x) => x.name).join(" > ");
report("S2 six carry ≈ 65 % (1 %), order I-133 > Xe-133 > I-131 > Cs-137 > Cs-134 > Ag-110m",
  Math.abs(S.sixBq / S.totalBq - 0.65) < 0.01 && order === "I-133 > Xe-133 > I-131 > Cs-137 > Cs-134 > Ag-110m", `${(100 * S.sixBq / S.totalBq).toFixed(2)} %, ${order}`);

// 10. The pages: widget, scripts, banner date, and their place in the list.
const kit = fs.readFileSync(path.join(__dirname, "../neutronics/lesson-kit.js"), "utf8");
const pos = (f) => kit.indexOf(`["${f}"`);
check("10 FISSION order: leaves-out < chem-air < chem-steam < atops-big-picture", pos("failure-leaves-out.html") < pos("chem-air.html") && pos("chem-air.html") < pos("chem-steam.html") && pos("chem-steam.html") < pos("atops-big-picture.html") ? 0 : 1, 0);
check("10 FISSION order: simplifications < atops-source-term", pos("atops-simplifications.html") > 0 && pos("atops-simplifications.html") < pos("atops-source-term.html") ? 0 : 1, 0);
[["chem-air.html", "ch-air"], ["chem-steam.html", "ch-steam"], ["atops-source-term.html", "ch-source"]].forEach(([p, id]) => {
  const html = fs.readFileSync(path.join(__dirname, p), "utf8");
  const ok = html.includes(`id="${id}"`) && html.includes('id="ch-numbers"') && html.includes('src="chemhand-data.js"') && html.includes('src="chemhand-story.js"') && html.includes("AI-assisted first draft (2026-11-04)") && html.includes("@@COMMIT@@") && html.includes('class="lesson-nav"') && html.includes('class="predict"');
  check(`10 ${p}: widget, data, banner, nav, footer, predict`, ok ? 0 : 1, 0);
  // Every data-ch key the page uses is one the story script fills.
  const story = fs.readFileSync(path.join(__dirname, "chemhand-story.js"), "utf8");
  const keys = [...html.matchAll(/data-ch="(\w+)"/g)].map((m) => m[1]);
  check(`10 ${p}: every data-ch key is filled (${keys.length})`, keys.filter((k) => !story.includes(k + ":")).length, 0);
});

// 11. No physics in the widget script: it draws recorded values only.
const story = fs.readFileSync(path.join(__dirname, "chemhand-story.js"), "utf8");
check("11 chemhand-story.js calls no exp/pow/log of its own", /Math\.(exp|pow|log)\b/.test(story) ? 1 : 0, 0);

if (failed) { console.log(`${failed} check(s) failed`); process.exit(1); }
console.log("all chemistry and hand-off checks passed");
